"""miner_2 2026-07-30 -- pairwise spearman correlation among new candidates and library.
Informs which candidates to persist (avoid persisting near-duplicates that will
just be evicted by the audit's pairwise correlation gate)."""
import sys
import numpy as np
import pandas as pd

sys.path.insert(0, "scripts")
from factor_validation_lib import (load_closes, load_index, factor_panel,
                                   load_library_panels)

close, vol, open_, high, low = load_closes()
macro = {k: load_index(k) for k in ["VIX", "DXY", "USDCNY", "USDJPY", "EURUSD"]}
for anchor in ["SPX", "XAU", "BTC", "WTI", "NDX", "US10Y"]:
    macro[anchor] = close[anchor].dropna()
lib = load_library_panels()


def _safe_div(a, b):
    with np.errstate(divide="ignore", invalid="ignore"):
        return a / b


def f_body_ratio_10(c, v, o, h, l, m, win=10):
    rng = (h - l).replace(0, np.nan)
    return _safe_div((c - o).abs(), rng).rolling(win).mean()


def f_vol_z_20(c, v, o, h, l, m, win=20):
    vv = np.log(v.replace(0, np.nan))
    return (vv - vv.rolling(win).mean()) / vv.rolling(win).std()


def f_mkt_corr_20(c, v, o, h, l, m, win=20):
    spx = m["SPX"].reindex(c.index).ffill().pct_change()
    return c.pct_change().rolling(win).corr(spx)


def f_downside_ratio_20(c, v, o, h, l, m, win=20):
    r = c.pct_change()
    tot = r.rolling(win).std()
    d = r.clip(upper=0).rolling(win).std()
    return _safe_div(d, tot)


def f_updown_freq_20(c, v, o, h, l, m, win=20):
    r = c.pct_change()
    return r.rolling(win).apply(lambda x: (x > 0).sum() / max((x != 0).sum(), 1), raw=True)


fns = {
    "body_ratio_10": f_body_ratio_10,
    "vol_z_20": f_vol_z_20,
    "mkt_corr_20": f_mkt_corr_20,
    "downside_ratio_20": f_downside_ratio_20,
    "updown_freq_20": f_updown_freq_20,
}
panels = {k: factor_panel(fn, close, vol, open_, high, low, macro) for k, fn in fns.items()}

names = list(panels.keys()) + list(lib.keys())
mat = pd.DataFrame(np.nan, index=names, columns=names)
for a in names:
    pa = panels.get(a, lib.get(a))
    for b in names:
        pb = panels.get(b, lib.get(b))
        m = pa.notna() & pb.notna()
        if m.sum().sum() >= 100:
            mat.loc[a, b] = pa[m].stack().rank().corr(pb[m].stack().rank())

print("Pairwise spearman rho (new candidates + library):")
print(mat.round(3).to_string())
print()
for a in names:
    pa = panels.get(a, lib.get(a))
    maxlib = max(abs(pa[mask].stack().rank().corr(lib[k][mask].stack().rank()))
                 for k, libp in lib.items()
                 for mask in [pa.notna() & libp.notna()] if mask.sum().sum() >= 100)
    print(f"{a:20s} max_abs_library_corr = {maxlib:.4f}")

"""miner_2 2026-07-30 -- cycle B screen: new candidate families, orthogonal
to current effective library (mom_10d_skip5, vix_beta_cond_60x20,
yield_beta_cond_60x20). Admission horizon = 10. Gate |IC|>=0.007, |ICIR|>=0.084.
Library correlation threshold 0.5.
"""
import sys
import numpy as np
import pandas as pd

sys.path.insert(0, "scripts")
from factor_validation_lib import (load_closes, load_index, factor_panel,
                                   ic_series, fwd_returns, coverage,
                                   turnover_rank, IC_GATE, ICIR_GATE)

close, vol, open_, high, low = load_closes()
vix = load_index("VIX")
dxy = load_index("DXY")
macro = {"VIX": vix, "DXY": dxy}
macro["US10Y"] = close["US10Y"].dropna()
macro["CN10Y"] = close["CN10Y"].dropna()
print(f"Panel {close.index[0].date()}..{close.index[-1].date()}, {len(close)} rows x {close.shape[1]} assets", flush=True)

# ---------------- library panels (recomputed from data, no artifacts needed) ----------------
def _beta(ar, mr, win):
    cov = ar.rolling(win).cov(mr)
    var = mr.rolling(win).var()
    return cov / var

def _reindex_macro(c, m):
    return m.reindex(c.index).ffill()

lib_panels = {}
# mom_10d_skip5
lp = {}
for a in close.columns:
    c = close[a].dropna()
    lp[a] = (c.shift(5) / c.shift(15) - 1.0).reindex(close.index)
lib_panels["mom_10d_skip5"] = pd.DataFrame(lp)
# vix_beta_cond_60x20
lp = {}
for a in close.columns:
    c = close[a].dropna()
    vs = _reindex_macro(c, vix)
    b = _beta(c.pct_change(), vs.pct_change(), 60)
    lp[a] = (-b * (vs / vs.shift(20) - 1.0)).reindex(close.index)
lib_panels["vix_beta_cond_60x20"] = pd.DataFrame(lp)
# yield_beta_cond_60x20 (US10Y)
lp = {}
for a in close.columns:
    c = close[a].dropna()
    ys = _reindex_macro(c, macro["US10Y"])
    b = _beta(c.pct_change(), ys.pct_change(), 60)
    lp[a] = (b * (ys / ys.shift(20) - 1.0)).reindex(close.index)
lib_panels["yield_beta_cond_60x20"] = pd.DataFrame(lp)
print("library panels reconstructed", flush=True)

def lib_corr(panel):
    best = 0.0
    for fid, lp in lib_panels.items():
        common = panel.index.intersection(lp.index)
        cols = [c for c in panel.columns if c in lp.columns]
        a = panel.loc[common, cols].values.ravel()
        b = lp.loc[common, cols].values.ravel()
        m = np.isfinite(a) & np.isfinite(b)
        if m.sum() < 200:
            continue
        rho = float(np.corrcoef(a[m], b[m])[0, 1])
        best = max(best, abs(rho))
    return round(best, 4)

# ---------------- forward returns ----------------
H = [1, 2, 3, 5, 10, 20]
fwd = {h: fwd_returns(close, h) for h in H}
print("forward returns ready", flush=True)

# ---------------- candidates ----------------
def rv(c, w):
    return c.pct_change().rolling(w).std()

def mean_hl(c, o, h, l, w):
    return ((h - l) / c).rolling(w).mean()

cands = {}

# A. volatility term-structure ratios
def f_volr_5x60(c, v, o, h, l, m):
    return rv(c, 5) / rv(c, 60) - 1.0
cands["vol_ratio_5x60"] = f_volr_5x60

def f_volr_10x60(c, v, o, h, l, m):
    return rv(c, 10) / rv(c, 60) - 1.0
cands["vol_ratio_10x60"] = f_volr_10x60

def f_volr_20x60(c, v, o, h, l, m):
    return rv(c, 20) / rv(c, 60) - 1.0
cands["vol_ratio_20x60"] = f_volr_20x60

def f_range_5x60(c, v, o, h, l, m):
    return mean_hl(c, o, h, l, 5) / mean_hl(c, o, h, l, 60) - 1.0
cands["range_ratio_5x60"] = f_range_5x60

# B. drawdown / distance from highs
def f_maxdd_60(c, v, o, h, l, m):
    return c / c.rolling(60).max() - 1.0
cands["max_dd_60"] = f_maxdd_60

def f_dist_high_60(c, v, o, h, l, m):
    return c / h.rolling(60).max() - 1.0
cands["dist_high_60"] = f_dist_high_60

def f_hl_pos_60(c, v, o, h, l, m):
    rng = h.rolling(60).max() - l.rolling(60).min()
    return (c - l.rolling(60).min()) / rng
cands["hl_pos_60"] = f_hl_pos_60

# C. trend persistence / autocorrelation
def f_autocorr_20(c, v, o, h, l, m):
    r = c.pct_change()
    return r.rolling(20).apply(lambda x: np.corrcoef(x[:-1], x[1:])[0, 1] if len(x) > 3 else np.nan, raw=True)
cands["autocorr_20"] = f_autocorr_20

def f_gain_loss_20(c, v, o, h, l, m):
    r = c.pct_change()
    pos = r.clip(lower=0).rolling(20).mean()
    neg = (-r.clip(upper=0)).rolling(20).mean()
    return pos / neg.replace(0, np.nan)
cands["gain_loss_20"] = f_gain_loss_20

def f_skew_20(c, v, o, h, l, m):
    return c.pct_change().rolling(20).skew()
cands["skew_20"] = f_skew_20

def f_vol_adj_mom_20(c, v, o, h, l, m):
    return (c / c.shift(20) - 1.0) / rv(c, 20)
cands["vol_adj_mom_20"] = f_vol_adj_mom_20

def f_vol_adj_mom_60(c, v, o, h, l, m):
    return (c / c.shift(60) - 1.0) / rv(c, 60)
cands["vol_adj_mom_60"] = f_vol_adj_mom_60

# D. volume dynamics
def f_vol_trend_5x60(c, v, o, h, l, m):
    if v is None:
        return pd.Series(np.nan, index=c.index)
    return v.rolling(5).mean() / v.rolling(60).mean() - 1.0
cands["vol_trend_5x60"] = f_vol_trend_5x60

def f_pv_corr_20(c, v, o, h, l, m):
    if v is None:
        return pd.Series(np.nan, index=c.index)
    r = c.pct_change()
    return r.rolling(20).corr(v.pct_change())
cands["pv_corr_20"] = f_pv_corr_20

# E. intraday / overnight structure
def f_oc_ratio_20(c, v, o, h, l, m):
    intra = (o - c).abs()
    over = (c - c.shift(1)).abs()
    return intra.rolling(20).mean() / over.rolling(20).mean()
cands["oc_ratio_20"] = f_oc_ratio_20

def f_body_ratio_60(c, v, o, h, l, m):
    body = (c - o).abs()
    rng = (h - l)
    return body.rolling(60).mean() / rng.rolling(60).mean()
cands["body_ratio_60"] = f_body_ratio_60

def f_upper_shadow_20(c, v, o, h, l, m):
    upper = (h - np.maximum(o, c))
    rng = (h - l)
    return (upper / rng.replace(0, np.nan)).rolling(20).mean()
cands["upper_shadow_20"] = f_upper_shadow_20

# F. short-term reversal / microstructure
def f_rev_1d(c, v, o, h, l, m):
    return -(c.pct_change())
cands["rev_1d"] = f_rev_1d

def f_rev_3d_skip1(c, v, o, h, l, m):
    return -(c.shift(1) / c.shift(4) - 1.0)
cands["rev_3d_skip1"] = f_rev_3d_skip1

# G. conditional rate beta on CN10Y (orthogonal to US10Y-based yield factor)
def f_cn10y_beta_cond_60x20(c, v, o, h, l, m):
    cs = _reindex_macro(c, m["CN10Y"])
    b = _beta(c.pct_change(), cs.pct_change(), 60)
    return b * (cs / cs.shift(20) - 1.0)
cands["cn10y_beta_cond_60x20"] = f_cn10y_beta_cond_60x20

# H. cross-sectional dispersion (each asset vs its own 10d group)
def f_rel_mom_10(c, v, o, h, l, m):
    return c.shift(1) / c.shift(11) - 1.0
cands["rel_mom_10_skip1"] = f_rel_mom_10

print(f"{len(cands)} candidates defined", flush=True)

# ---------------- run ----------------
rows = []
for name, fn in cands.items():
    try:
        panel = factor_panel(fn, close, vol, open_, high, low, macro)
    except Exception as e:
        print(f"{name}: ERROR {e}", flush=True)
        continue
    cov_ad, cov_ge8 = coverage(panel)
    if cov_ge8 < 0.05:
        print(f"{name}: skip low coverage ge8={cov_ge8:.3f}", flush=True)
        continue
    icm = ic_series(panel, fwd[10])
    ic = float(icm.mean()) if len(icm) else np.nan
    icir = float(icm.mean() / icm.std()) if len(icm) > 2 else np.nan
    hit = float((icm > 0).mean()) if np.isfinite(ic) else np.nan
    if ic < 0:
        hit = float((icm < 0).mean())
    decay = {str(h): round(float(ic_series(panel, fwd[h]).mean()), 4) if len(ic_series(panel, fwd[h])) else np.nan for h in H}
    to = turnover_rank(panel)
    lc = lib_corr(panel)
    gate = abs(ic) >= IC_GATE and abs(icir) >= ICIR_GATE
    rows.append((name, ic, icir, hit, len(icm), cov_ad, cov_ge8, to, lc, gate, decay))
    print(f"{name:28s} ic={ic: .4f} icir={icir: .4f} hit={hit:.3f} n={len(icm):4d} "
          f"cov={cov_ad:.3f}/{cov_ge8:.2f} to={to:.2f} libcorr={lc:.3f} "
          f"{'PASS' if gate else 'fail'}", flush=True)

print("\n--- PASSING (gate + corr<0.5) ---")
for r in rows:
    if r[9] and r[8] < 0.5:
        print(f"{r[0]:28s} ic={r[1]: .4f} icir={r[2]: .4f} libcorr={r[8]:.3f} decay={r[10]}")

